    'archetype.comeback.title': 'Возвращение',
    'archetype.comeback.description': 'В вашей истории есть перерыв в {gap_days} дней — и вы вернулись. Это реже, чем ровная серия.',
    'archetype.comeback.kindred': 'Мигель де Сервантес',
    'archetype.comeback.kindredWhy': 'Пять лет плена, долгое молчание — и «Дон Кихот», написанный, когда ему было под шестьдесят.',
    'archetype.ironclad.title': 'Несгибаемая цепь',
