    'archetype.ironclad.kindred': 'Иммануил Кант',
    'archetype.ironclad.kindredWhy': 'По кёнигсбергской легенде, соседи сверяли часы по его ежедневной прогулке.',
    'archetype.deep_diver.title': 'Глубокое погружение',
    'archetype.deep_diver.description': '{long_pct}% ваших дней длиннее полутора часов. Вы не заглядываете в книгу — вы в неё уходите.',
    'archetype.deep_diver.kindred': 'Мишель де Монтень',
    'archetype.deep_diver.kindredWhy': 'Заперся в башне с тысячей книг и вышел оттуда с «Опытами».',
    'archetype.marathoner.title': 'Долгое дыхание',
    'archetype.marathoner.description': 'В среднем {avg_minutes} минут в день чтения. Это дистанция, а не заход на пару страниц.',
    'archetype.marathoner.kindred': 'Умберто Эко',
    'archetype.marathoner.kindredWhy': 'Держал дома тридцать тысяч томов и повторял, что ценны в библиотеке как раз непрочитанные.',
    'archetype.metronome.title': 'Метроном',
    'archetype.metronome.description': 'Стабильность {consistency_pct}%, и минуты изо дня в день почти не пляшут. Вы читаете с точностью часового механизма.',
    'archetype.metronome.kindred': 'Чарльз Дарвин',
    'archetype.metronome.kindredWhy': 'Жил по расписанию до минуты: работа, прогулка по «тропе размышлений», вечернее чтение вслух.',
    'archetype.norm_keeper.title': 'Точная мера',
    'archetype.norm_keeper.description': '{norm_pct}% ваших дней — это тридцать с небольшим минут. Вы берёте ровно норму и не тратите лишнего.',
    'archetype.norm_keeper.kindred': 'Сенека',
    'archetype.norm_keeper.kindredWhy': 'Советовал читать немногих авторов, но до конца: «быть повсюду — значит не быть нигде».',
    'archetype.deadline_dancer.title': 'Финишный рывок',
    'archetype.deadline_dancer.description': '{late_pct}% ваших минут приходится на последнюю декаду месяца. Круг вы закрываете на флажке — но закрываете.',
    'archetype.deadline_dancer.kindred': 'Фёдор Достоевский',
    'archetype.deadline_dancer.kindredWhy': 'Написал «Игрока» за двадцать шесть дней, чтобы успеть к сроку, вписанному в контракт.',
    'archetype.fast_starter.title': 'С места в карьер',
    'archetype.fast_starter.description': '{early_pct}% минут вы набираете в первые десять дней круга. Вы уже бежите, пока другие разминаются.',
    'archetype.fast_starter.kindred': 'Виктор Гюго',
    'archetype.fast_starter.kindredWhy': 'Запирал одежду в шкаф, чтобы не выйти из дома, пока не сделана дневная норма.',
    'archetype.weekday_loyalist.title': '{weekday} — ваш день для чтения',
    'archetype.weekday_loyalist.description': 'Львиная доля вашего чтения приходится на дни по {weekday}. У вас есть свой день недели.',
    'archetype.weekday_loyalist.kindred': 'Хорхе Луис Борхес',
    'archetype.weekday_loyalist.kindredWhy': 'И читал, и работал в одном и том же месте — Национальной библиотеке, которой сам руководил.',
    'archetype.weekend_reader.title': 'Тишина выходных',
    'archetype.weekend_reader.description': '{weekend_pct}% ваших минут — суббота и воскресенье. Будни уходят делам, книги ждут тишины.',
    'archetype.weekend_reader.kindred': 'Шакарим Кудайбердиулы',
    'archetype.weekend_reader.kindredWhy': 'Уходил в горы и годами читал и писал вдали от чужого шума.',
    'archetype.finisher.title': 'До последней страницы',
    'archetype.finisher.description': 'Вы дочитали книгу в {finish_pct}% своих кругов. Начатое у вас доходит до конца.',
    'archetype.finisher.kindred': 'Лев Толстой',
    'archetype.finisher.kindredWhy': 'Составил «Круг чтения» — календарь на каждый день года из того, что прочёл сам.',
    'archetype.omnivore.title': 'Всеядный читатель',
    'archetype.omnivore.description': '{books} дочитанных книг. Вас никогда не держала одна полка.',
    'archetype.omnivore.kindred': 'Теодор Рузвельт',
    'archetype.omnivore.kindredWhy': 'По свидетельствам современников, проглатывал по книге в день — от античных историков до вестернов.',
    'archetype.on_the_rise.title': 'Восходящая кривая',
    'archetype.on_the_rise.description': 'Сейчас вы читаете по {second_half_avg} минут против {first_half_avg} в начале пути. Кривая идёт вверх.',
    'archetype.on_the_rise.kindred': 'Малкольм Икс',
    'archetype.on_the_rise.kindredWhy': 'По-настоящему выучился читать в тюрьме, переписав от руки весь словарь, страница за страницей.',
    'archetype.steady.title': 'Ровное пламя',
    'archetype.steady.description': '{consistency_pct}% стабильности, без рывков и без провалов. Вы не разгоняетесь и не гаснете.',
    'archetype.steady.kindred': 'Харуки Мураками',
    'archetype.steady.kindredWhy': 'Каждый день одно и то же: рано встать, работать, бежать, лечь. Годами.',
    'archetype.sprinter.title': 'Вспышками',
    'archetype.sprinter.description': 'Мощные дни сменяются затишьем. Вы читаете разрядами, а не ровным током.',
    'archetype.sprinter.kindred': 'Оноре де Бальзак',
    'archetype.sprinter.kindredWhy': 'Садился за стол в полночь и работал по пятнадцать часов подряд, а потом падал без сил.',
    'archetype.slow_burn.title': 'Тихий огонь',
    'archetype.slow_burn.description': 'В среднем {avg_minutes} минут в день — немного, но почти без пропусков. Понемногу и очень долго.',
    'archetype.slow_burn.kindred': 'Джейн Остин',
    'archetype.slow_burn.kindredWhy': 'Писала и читала урывками в общей гостиной, пряча листы, когда скрипела дверь.',
    'archetype.veteran.title': 'Старожил кругов',
