    // About
    'about.kicker': 'Наша история',
    'about.title': 'От гугл-таблицы до платформы',
    'about.p1': 'PowerBook начался 24 февраля 2021 года, в локдаун. Трое друзей — Айсултан, Нурбол и Мадияр — жили в разных городах и решили читать вместе: не гнаться за количеством книг, а просто читать каждый день и вечером отчитываться друг перед другом. Никакого приложения — только общая таблица и обещание не бросать.',
    'about.p2': 'После первого месяца мы рассказали о кругах другим, и многие захотели присоединиться. Стало ясно, что это не только наша история, а система, которая помогает выстроить привычку. Дальше сообщество росло почти целиком из уст в уста.',
    'about.p4': 'Но главное — не статистика. Есть люди, которые в этом месяце не прочитали бы ни минуты, если бы PowerBook не существовало. Ноль превратился в тридцать минут, тридцать минут — в ещё один день, а день — в привычку, которая может остаться на всю жизнь.',
    'about.growthTitle': 'Как росло сообщество',
    'about.growthHint': 'читателей в год',
    'about.growthFoot': '* текущий год ещё идёт. Каждый год — это люди, которые читали хотя бы один день.',
    'showcase.title': 'Как проходили наши круги',
    'showcase.subtitle': 'Каждый квадрат — это день, когда кто-то читал. Чем ярче, тем больше людей отметились.',
    'showcase.calTitle': 'Активность за',
    'showcase.calLegend': 'участников в день',
    'showcase.calFoot': 'Это только часть истории — в архиве есть каждый год и каждый день.',
    'showcase.openArchive': 'Открыть архив',
    'quiet.q1': 'Комната без книг подобна телу без души.',
    'quiet.a1': 'Цицерон',
    'quiet.q2': 'Читай не для того, чтобы возразить, а чтобы подумать.',
    'quiet.a2': 'Сенека',
    'quiet.q3': 'Знание — самое ценное богатство человека.',
    'quiet.a3': 'Абай Құнанбайұлы',
    'quiet.q4': 'Хорошая книга не та, что легко читается, а та, что остаётся с тобой.',
    'quiet.a4': 'Мишель де Монтень',
    'quiet.q5': 'Чтение хороших книг — разговор с лучшими умами прошлого.',
    'quiet.a5': 'Рене Декарт',
    'quiet.q6': 'Вложение в знания приносит лучшие проценты.',
    'quiet.a6': 'Бенджамин Франклин',
    'quiet.q7': 'Чем больше знаешь, тем сильнее чувствуешь, как мало знаешь.',
    'quiet.a7': 'Лев Толстой',
    'quiet.q8': 'Человек, который много читает, редко бывает одинок.',
    'quiet.a8': 'Фёдор Достоевский',
