    'legal.contact': 'Questions about these terms —',
    'privacy.title': 'Privacy Policy',
    'privacy.updated': 'Updated 15 October 2026',
    'privacy.intro': 'PowerBook is a reading community. This page describes plainly what we collect, why, and what happens when you delete your account. We do not sell your data and we do not show ads.',
    'privacy.sectionCount': '9',
    'privacy.s1.title': '1. Account data',
    'privacy.s1.body': 'When you register we store your username, display name, gender and Telegram username. Your password is stored only as a hash — neither we nor anyone else can recover it. You may optionally add an avatar, a recommendation note, a music link and a list of favourite books.\n\nIn the “How are you finding PowerBook?” window you can leave feedback and a photo. We keep them to make the service better. We use the photo in PowerBook’s materials (the site, the app, social media, videos) without your name, and only if you are 18 or older and ticked that we may; if you change your mind, write to us: we will take it down where we can and stop using it.',
    'privacy.s2.title': '2. Reading data',
    'privacy.s2.body': 'We store your daily entries: the date, the number of minutes, whether you finished a book, and any comment you left. This is the core of the service — circles, statistics, the archive and the Hall of Fame are all built from these records.',
    'privacy.s3.title': '3. Uploaded books',
    'privacy.s3.body': 'Files you upload to your personal library (PDF and EPUB) are stored on our server and are accessible only to you. We do not hand them to other users, publish them, or expose them via a shareable link. Other readers can see only the title, author, cover and reading percentage — and only if you have not hidden the book.',
    'privacy.s4.title': '4. What others can see',
    'privacy.s4.body': 'Publicly visible: your name, Telegram username, avatar, reading statistics, finished books and circle participation. The archive and Hall of Fame are open to everyone, including visitors who are not signed in. If that does not suit you, leave the optional profile fields empty.',
    'privacy.s5.title': '5. Where data is stored',
    'privacy.s5.body': 'Data sits on our own server. There are no advertising networks. The external services we use:\n\n— Telegram, for sign-in and password recovery; at that moment Telegram passes us your public profile. Our Telegram bot also tells the team about new feedback: your username and the text of the feedback (the photos themselves stay on our server); and about who has not logged reading for a while and that you answered a private message — your name only, never the message text.\n— Google Analytics, to see which parts of the site are used. It sees the pages opened and actions taken on the site together with your account number, never your name or e-mail.\n— Sentry, to learn about errors on the site: again only the account number, without your name or IP address.\n— Google Books, Open Library and Wikipedia, to find book covers and descriptions; only book titles are sent there.\n— DeepSeek, for the AI features: the reading letters, the circle review and talking about a book. When you use them, what the answer needs is sent there: the books, your marks, reviews and notes on them, your reading minutes and your messages in the AI book chat, without your name or contacts. Private messages are never sent there.',
    'privacy.s6.title': '6. Private messages',
    'privacy.s6.body': 'If you have not logged reading for a few days, PowerBook may send you a short message — at most two per break, at the time you usually read. You can answer right on the site: the founder reads the answers and replies himself.\n\n— Messages are stored on our server in Kazakhstan (Astana). You and the PowerBook team see them.\n— The text of your answers is never sent to outside services — not to Telegram, analytics or AI. A phone notification goes through Apple’s or Google’s services.\n— You can switch these messages off in the bell: “Personal messages”.\n— The conversation is deleted with your account. It may stay in server backups for a while, until those are replaced.',
    'privacy.s7.title': '7. Deleting your account',
    'privacy.s7.body': 'You can delete your account from your profile, under "Danger zone" — on the website as well as in the app. Deletion permanently removes your login and password, Telegram username, email, avatar, profile text, every book file you uploaded, the feedback and photos you sent through “How are you finding PowerBook?”, and all your private messages. The copy of your feedback text that already reached the team’s Telegram we delete by hand — just write to us.\n\nWhat remains is anonymised reading activity in past circle archives — minutes per day. It is no longer linked to your name and cannot identify you, but it is kept so the history and statistics of everyone who read alongside you are not broken.',
    'privacy.s8.title': '8. Children',
    'privacy.s8.body': 'The service is not intended for children under 13. If you learn that a child has created an account, write to us and we will remove it.',
    'privacy.s9.title': '9. Changes',
    'privacy.s9.body': 'If this policy changes we will update the date at the top of the page. Significant changes will be announced in the community.',
    'terms.title': 'Terms of Use',
    'terms.updated': 'Updated 15 October 2026',
    'terms.intro': 'By using PowerBook you agree to these terms. They are deliberately written in plain language.',
    'terms.sectionCount': '7',
    'terms.s1.title': '1. What PowerBook is',
    'terms.s1.body': 'PowerBook is a free reading community: monthly circles, daily reading entries, statistics and a personal library. The service is non-commercial and there is no charge.',
    'terms.s2.title': '2. Your account',
    'terms.s2.body': 'You are responsible for keeping your password safe and for activity under your account. Use your real Telegram username — it is used for sign-in, account recovery and contact within your circle.',
    'terms.s3.title': '3. Uploaded files and copyright',
    'terms.s3.body': 'By uploading a book you confirm you are entitled to keep a copy of it for your own reading. Your library is private: files are never handed to other users or published — the service is not a way to distribute books.\n\nWe do not inspect the contents of uploaded files, but we will remove material on a valid rights-holder request. Repeated infringement may result in the account being suspended.',
    'terms.s4.title': '4. Acceptable use',
    'terms.s4.body': 'You may not impersonate someone else, inflate your statistics with false entries, upload malicious files, attempt to reach other people\'s data, interfere with the operation of the service, or spam or insult people in private messages.',
    'terms.s5.title': '5. No warranty',
    'terms.s5.body': 'The service is provided "as is". We work to avoid losing data and to keep backups, but we cannot guarantee uninterrupted operation. Keep your own copies of files that matter to you.',
    'terms.s6.title': '6. Changes to these terms',
    'terms.s6.body': 'These terms may be updated. The date of the last change is shown at the top of the page.',
    'terms.s7.title': '7. Rights-holder requests',
    'terms.s7.body': 'If you are a rights holder and believe your material is stored in a user\'s private library, write to madik.orynbay@gmail.com with "Copyright" in the subject line.\n\nInclude: which work, evidence of your rights, and a contact for our reply. We review such requests within 5 working days and remove the material once confirmed. Repeated infringement results in the account being suspended.',
