    // About
    'about.kicker': 'Our story',
    'about.title': 'From a spreadsheet to a platform',
    'about.p1': 'PowerBook started on 24 February 2021, during lockdown. Three friends — Aisultan, Nurbol and Madiyar — were living in different cities and decided to read together: not to race through as many books as possible, but simply to read every day and tell each other about it in the evening. No app — just a shared spreadsheet and a promise not to quit.',
    'about.p2': 'After the first month we told other people about the marathon, and many of them wanted to join. It became clear this wasn\'t only our story, but a system that helps people build the habit. From there the community grew almost entirely by word of mouth.',
    'about.p4': 'But the point was never the statistics. There are people who wouldn\'t have read a single minute this month if PowerBook didn\'t exist. Zero became thirty minutes, thirty minutes became another day, and a day became a habit that can stay with someone for life.',
    'about.growthTitle': 'How the community grew',
    'about.growthHint': 'readers per year',
    'about.growthFoot': '* the current year is still running. Each year counts people who read on at least one day.',
    'showcase.title': 'How our circles have run',
    'showcase.subtitle': 'Every square is a day someone read. The brighter it is, the more people logged that day.',
    'showcase.calTitle': 'Activity in',
    'showcase.calLegend': 'readers per day',
    'showcase.calFoot': "That's only part of it — the archive has every year and every day.",
    'showcase.openArchive': 'Open the archive',
    'quiet.q1': 'A room without books is like a body without a soul.',
    'quiet.a1': 'Цицерон',
    'quiet.q2': 'Read not to contradict, but to think.',
    'quiet.a2': 'Сенека',
    'quiet.q3': 'Knowledge is a person\'s most valuable wealth.',
    'quiet.a3': 'Абай Құнанбайұлы',
    'quiet.q4': 'A good book is not the one read easily, but the one that stays with you.',
    'quiet.a4': 'Мишель де Монтень',
    'quiet.q5': 'Reading good books is a conversation with the finest minds of the past.',
    'quiet.a5': 'Рене Декарт',
    'quiet.q6': 'An investment in knowledge pays the best interest.',
    'quiet.a6': 'Бенджамин Франклин',
    'quiet.q7': 'The more you know, the more you feel how little you know.',
    'quiet.a7': 'Лев Толстой',
    'quiet.q8': 'Someone who reads a great deal is rarely lonely.',
    'quiet.a8': 'Фёдор Достоевский',
    'quiet.q9': 'A book is what makes silence interesting.',
    'quiet.a9': 'Антон Чехов',
    'quiet.q10': 'One who does not read is no better off than one who cannot.',
    'quiet.a10': 'Марк Твен',
    'quiet.q11': 'A book should wake you, not lull you to sleep.',
    'quiet.a11': 'Франц Кафка',
    'quiet.q12': 'To learn and to review what you have learned — is that not a joy?',
    'quiet.a12': 'Конфуций',
    'quiet.q13': 'Reading is the best learning there is.',
    'quiet.a13': 'Александр Пушкин',
    'quiet.q14': 'I know only that I know nothing.',
    'quiet.a14': 'Сократ',
    'quiet.finishLabel': 'Finish line',
    'quiet.finishText': 'The circle is over — results are being tallied and books handed out.',
