    // What PowerBook is: the explainer section and its video
    'ex.kicker': 'How it works',
    'ex.title': 'What a PowerBook circle is',
    'ex.lead': 'Every month is a new circle: you read at least 30 minutes a day together with the community and log the minutes on the site. It is not a race for speed or book counts — it is how you build the habit of reading every day.',
    'ex.stepsTitle': 'How a circle goes — 4 steps',
    'ex.step1.t': 'Sign up between the 1st and the 10th',
    'ex.step1.d': 'Sign-up is free. Missed it? Join the waiting list for the next circle.',
    'ex.step2.t': 'Read 30+ minutes every day',
    'ex.step2.d': 'Any book you choose. The easy way: the reading room, with a timer.',
    'ex.step3.t': 'Log your minutes on the site',
    'ex.step3.d': 'Before bed the same day. 30 minutes or more and the day counts; less, and it does not. You can fill in past days, but do it at least once a week.',
    'ex.step4.t': 'The last day is for corrections',
    'ex.step4.d': 'Until 20:00 Astana time you can fix your entries — the day itself does not count. Then the circle sums up its shared total, and the book swap begins.',
    'ex.getTitle': 'What you get in a month',
