    'review.tip.fixed_slot.t': 'A fixed time for the book',
    'review.tip.fixed_slot.d': 'Tie reading to one time of day — 20 minutes after breakfast or before bed. With the time fixed, there is nothing to decide each day.',
    'review.tip.habit_stack.t': 'Stack it on a habit',
    'review.tip.habit_stack.d': 'Read right after something you already do daily: coffee, the commute, dinner. "After tea, 10 minutes" beats "I will read when I have time".',
    'review.tip.weekend_plan.t': 'A weekend plan',
    'review.tip.weekend_plan.d': 'Routines slip at weekends. Decide in advance when you will read on Saturday and Sunday — say, in the morning, before the phone.',
    'review.tip.mid_month.t': 'A second wind',
    'review.tip.mid_month.d': 'Drive dips by mid-month. Set yourself a goal for the 15th and mark it — a second start is easier than the first.',
    'review.tip.reading_room.t': 'The reading room',
    'review.tip.reading_room.d': 'When starting is hard, open the PowerBook reading room and start the timer: reading beside others is easier, and the minutes go into "Today" by themselves.',
    'review.tip.start_strong.t': 'A strong start',
    'review.tip.start_strong.d': 'The first days set the tone for the whole circle. Pick the book in advance and begin on the 1st — even with 15 minutes.',
    'review.tip.two_by_fifteen.t': 'Two times fifteen',
    'review.tip.two_by_fifteen.d': 'If 30 minutes in one go will not happen, split it: 15 in the morning, 15 at night. Days of 10–20 minutes can almost always reach the goal.',
    'review.tip.never_twice.t': 'Never miss twice',
    'review.tip.never_twice.d': 'Missing a day is fine. What matters is not missing two in a row: after a miss, read at least 10 minutes the next day.',
    'review.tip.carry_book.t': 'Keep a book on you',
    'review.tip.carry_book.d': 'Keep a book, or a file on your phone, within reach: queues, commutes and waiting add up to 15–20 minutes a day.',
    'review.tip.audiobooks.t': 'Audio on the go',
    'review.tip.audiobooks.d': 'On days with no time for paper, listen to the audio version while travelling or doing chores — fewer empty days.',
    'review.tip.steady.t': 'Steady, not in bursts',
    'review.tip.steady.d': 'One three-hour day does not replace a week of 30 minutes. A little every day beats catching up at the weekend.',
    'review.tip.finish_line.t': 'To the finish line',
    'review.tip.finish_line.d': 'Many minutes, no book finished. Set a finish date or read a shorter book alongside — a finished book gives strength for the next.',
    'review.tip.look_back.t': 'What helped before',
    'review.tip.look_back.d': 'This circle was harder than the last. Recall what helped then — the time, the place, the book — and bring it back.',
    'review.tip.phone_away.t': 'Phone in another room',
    'review.tip.phone_away.d': 'While reading, put the phone away or switch on Do Not Disturb — attention lasts longer and the minutes add up.',
    'review.tip.before_sleep.t': 'Before sleep',
    'review.tip.before_sleep.d': '15–20 minutes of a book before bed instead of the feed — the day counts, and sleep comes easier.',
    'review.tip.track_pages.t': 'A goal in minutes',
    'review.tip.track_pages.d': 'Count minutes, not pages: 30 minutes a day is 15 hours a month and a couple of dozen books a year. A thick novel and a book of poems count the same.',

