export type TranslationKey = keyof typeof translations.ru;

type I18nContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: TranslationKey | string, params?: Record<string, string | number>) => string;
};

const I18nContext = createContext<I18nContextValue | null>(null);

/** «67-й круг», «67-ші айналым», «67th circle»: which circle this is, in the reader's language. */
export function circleOrdinal(locale: Locale, n: number, noun = true): string {
  if (locale === 'kk') {
    // the suffix follows the last spoken word of the number: жеті → -ші, алты → -шы, он → -шы
    const units: Record<number, string> = { 1: 'ші', 2: 'ші', 3: 'ші', 4: 'ші', 5: 'ші', 6: 'шы', 7: 'ші', 8: 'ші', 9: 'шы' };
    const tens: Record<number, string> = { 1: 'шы', 2: 'шы', 3: 'шы', 4: 'шы', 5: 'ші', 6: 'шы', 7: 'ші', 8: 'ші', 9: 'шы' };
    const sfx = n % 10 ? units[n % 10] : n % 100 ? tens[Math.floor((n % 100) / 10)] : 'ші';
    return noun ? `${n}-${sfx} айналым` : `${n}-${sfx}`;
  }
  if (locale === 'en') {
    const k = n % 100;
    const sfx = k >= 11 && k <= 13 ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' } as Record<number, string>)[n % 10] ?? 'th';
    return noun ? `${n}${sfx} circle` : `${n}${sfx}`;
  }
  return noun ? `${n}-й круг` : `${n}-й`;
}

function inKazakhstan(): boolean {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
    return /^Asia\/(Almaty|Qostanay|Aqtobe|Aqtau|Atyrau|Oral|Qyzylorda)$/.test(tz);
  } catch {
    return false;
  }
}

function getInitialLocale(): Locale {
  const saved = localStorage.getItem(STORAGE_KEY_LOCALE);
  if (saved === 'ru' || saved === 'kk' || saved === 'en') return saved;
  // Detect from browser
  const browserLang = navigator.language.slice(0, 2);
  if (browserLang === 'kk') return 'kk';
  // Many phones in Kazakhstan run in English while their owners read the
  // circle in Russian (GA4, Oct 2026: 40 of 104 home visitors). English is
  // for readers abroad; a Kazakhstan clock means Russian. The switch stays.
  if (browserLang === 'en') return inKazakhstan() ? 'ru' : 'en';
  return 'ru';
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(getInitialLocale);

  const setLocale = useCallback((newLocale: Locale) => {
    localStorage.setItem(STORAGE_KEY_LOCALE, newLocale);
    setLocaleState(newLocale);
  }, []);

  // Keep the document's language in step with the chosen one. Screen readers
  // and hyphenation follow this, and some browsers use it to decide how a
  // native date field is formatted — which is why an English page could still
  // show a Russian date placeholder.
  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  const t = useCallback(
    (key: TranslationKey | string, params?: Record<string, string | number>): string => {
      const localeTranslations = translations[locale] as Record<string, string>;
      const ruTranslations = translations.ru as Record<string, string>;
      let text = localeTranslations[key] ?? ruTranslations[key] ?? key;
      if (params) {
        Object.entries(params).forEach(([k, v]) => {
          text = text.replace(`{${k}}`, String(v));
        });
      }
      return text;
    },
    [locale]
  );

  const value = useMemo(() => ({ locale, setLocale, t }), [locale, setLocale, t]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext);
  if (!ctx) {
    throw new Error('useI18n must be used within I18nProvider');
  }
  return ctx;
}

export const LOCALES: { code: Locale; label: string }[] = [
  { code: 'ru', label: 'Рус' },
  { code: 'kk', label: 'Қаз' },
  { code: 'en', label: 'Eng' },
];


